const anniversaryMusic = document.getElementById("anniversaryMusic");
anniversaryMusic.addEventListener("error", () => {
  console.error("Could not load the anniversary audio:", anniversaryMusic.currentSrc);
});
let timers = [];
const later = (fn, ms) => timers.push(setTimeout(fn, ms));

function startAnniversaryMusic() {
  anniversaryMusic.play().catch(error => {
    if (error.name === "NotAllowedError") {
      document.addEventListener("pointerdown", () => {
        anniversaryMusic.play().catch(playError => {
          console.error("Could not play the anniversary audio.", playError);
        });
      }, { once: true });
    } else {
      console.error("Could not play the anniversary audio.", error);
    }
  });
}

function make(m) {
  const el = document.createElement("div");
  el.className = "notif";
  el.setAttribute("role", "status");
  el.innerHTML = `${LOGO}
    <div class="copy">
      <div class="top"><span class="app">Messenger</span><span class="when">now</span></div>
      <div class="who">${m.who}</div>
      <div class="msg">${m.text}</div>
    </div>`;
  stack.appendChild(el);
  el.style.zIndex = 50 - stack.children.length; // each new one slides out from behind the previous
  void el.offsetWidth; // commit start state
  return el;
}

const reveal = document.getElementById("reveal");
const rv = document.getElementById("rv");
let revealing = false;
function typeInto(text) {
  rv.innerHTML = "";
  let n = 0;
  text.split(" ").forEach((word, wi, arr) => {
    const w = document.createElement("span");
    w.className = "w";
    [...word].forEach(ch => {
      const c = document.createElement("span");
      c.className = "c";
      c.textContent = ch;
      c.style.animationDelay = (n++ * 55) + "ms";
      w.appendChild(c);
    });
    rv.appendChild(w);
    if (wi < arr.length - 1) { rv.appendChild(document.createTextNode(" ")); n++; }
  });
  return n * 55 + 600;
}
const pc = document.getElementById("petals");
const pctx = pc.getContext("2d");
let petals = [], petalRAF = 0, petalLast = 0, PW = 0, PH = 0;
const SPR = ["data:image/png;base64,"].map(src => { const im = new Image(); im.src = src; return im; });
function sizePetals() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  PW = window.innerWidth; PH = window.innerHeight;
  pc.width = PW * dpr; pc.height = PH * dpr;
  pctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
function newPetal(initial) {
  return {
    x: Math.random() * PW,
    y: initial ? -Math.random() * PH * 1.1 - 20 : -30 - Math.random() * 60,
    k: 0,
    s: 24 + Math.random() * 20,
    vy: 38 + Math.random() * 50,
    sway: 18 + Math.random() * 34,
    sf: .5 + Math.random() * .9,
    ph: Math.random() * 6.28,
    rot: Math.random() * 6.28,
    vr: (Math.random() - .5) * 1.6,
    flip: Math.random() * 6.28,
    vf: 1 + Math.random() * 1.8,
    a: .92 + Math.random() * .08,
    t: 0
  };
}
function drawPetal(p) {
  const im = SPR[p.k];
  if (!im.complete || !im.naturalWidth) return;
  const w = p.s * (p.k ? .85 : 1);
  const h = w * im.naturalHeight / im.naturalWidth;
  pctx.save();
  pctx.translate(p.x + Math.sin(p.t * p.sf + p.ph) * p.sway, p.y);
  pctx.rotate(p.rot);
  pctx.scale(Math.max(.2, Math.abs(Math.cos(p.flip))), 1);
  pctx.globalAlpha = p.a;
  pctx.shadowColor = "rgba(40,30,20,.38)";
  pctx.shadowBlur = 7;
  pctx.shadowOffsetX = 3;
  pctx.shadowOffsetY = 6;
  pctx.drawImage(im, -w / 2, -h / 2, w, h);
  pctx.restore();
}
function petalFrame(now) {
  const dt = Math.min(.05, (now - petalLast) / 1000 || .016);
  petalLast = now;
  pctx.clearRect(0, 0, PW, PH);
  for (let i = 0; i < petals.length; i++) {
    const p = petals[i];
    p.t += dt; p.y += p.vy * dt; p.rot += p.vr * dt; p.flip += p.vf * dt;
    if (p.y > PH + 30) petals[i] = newPetal(false);
    drawPetal(petals[i]);
  }
  petalRAF = requestAnimationFrame(petalFrame);
}
function startPetals() {
  sizePetals();
  const n = Math.round(Math.min(70, Math.max(34, PW / 12)));
  petals = Array.from({ length: n }, () => newPetal(true));
  petalLast = performance.now();
  cancelAnimationFrame(petalRAF);
  petalRAF = requestAnimationFrame(petalFrame);
}
window.addEventListener("resize", () => { if (petals.length) sizePetals(); });


