let letterOpen = false;
function openLetter() {
  if (letterOpen) return;
  letterOpen = true;
  const wrap = document.getElementById("envwrap");
  const paper = document.getElementById("paper");
  const sheet = document.getElementById("sheet");
  wrap.classList.remove("ready");
  wrap.removeAttribute("tabindex");
  sheet.innerHTML = '<h2 class="ln"></h2>' + LETTER.lines.map(() => '<p class="ln"></p>').join("") + '<p class="sign ln"></p>';
  const nodes = sheet.querySelectorAll(".ln");
  nodes[0].textContent = LETTER.title;
  LETTER.lines.forEach((t, i) => nodes[i + 1].textContent = t);
  nodes[nodes.length - 1].textContent = LETTER.sign;
  nodes.forEach((n, i) => n.style.transitionDelay = (1.3 + i * 0.3) + "s");
  // start the paper at the envelope, then rise and unfold to centre
  const er = wrap.getBoundingClientRect();
  const rr = reveal.getBoundingClientRect();
  const dx = (er.left + er.width / 2) - (rr.left + rr.width / 2);
  const dy = (er.top + er.height / 2) - (rr.top + rr.height / 2);
  const from = "translate(calc(-50% + " + dx + "px),calc(-50% + " + dy + "px)) scale(.12) rotate(-8deg)";
  const mid  = "translate(calc(-50% + " + dx * .3 + "px),calc(-50% + " + (dy * .3 - 40) + "px)) scale(.7) rotate(3deg)";
  const to   = "translate(-50%,-50%) scale(1) rotate(0deg)";
  paper.classList.add("show");
  const reduce = window.matchMedia("(prefers-reduced-motion:reduce)").matches;
  const a = paper.animate(
    [{ transform: from, opacity: 0 }, { transform: mid, opacity: 1, offset: .45 }, { transform: to, opacity: 1 }],
    { duration: reduce ? 1 : 1700, easing: "cubic-bezier(.2,.8,.25,1)", fill: "forwards" }
  );
  setTimeout(() => wrap.classList.add("gone"), 350);
  let armed = true;
  let banner = null, ticking = false;
  const dismiss = () => {
    if (!banner) return;
    const el = banner; banner = null;
    el.classList.add("out"); setTimeout(() => el.remove(), 700);
  };
  const check = () => {
    if (!letterOpen || !paper.classList.contains("read")) return;
    const st = sheet.scrollTop, left = sheet.scrollHeight - sheet.clientHeight - st; // single layout read
    if (left < 40) {
      if (armed) { armed = false; banner = popBanner({ who: "Sajil", text: LOVE_MSG }, () => { banner = null; backToChat(); }); }
    } else if (left > 120) armed = true;
    if (st <= 8) { armed = true; dismiss(); } // back at the very top: the notification goes away
  };
  // run at most once per frame (assigning onscroll replaces any older handler when the letter is reopened)
  sheet.onscroll = () => {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => { ticking = false; check(); });
  };
  a.onfinish = () => {
    paper.classList.add("read");
    // lines fade in one by one; if the whole letter already fits, the end is in view once they finish
    setTimeout(check, (1.3 + nodes.length * 0.3 + 1) * 1000);
  };
  if (navigator.vibrate) try { navigator.vibrate(12) } catch (e) {}
}
function closeLetter() {
  if (!letterOpen) return;
  const paper = document.getElementById("paper");
  paper.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 400, fill: "forwards" }).onfinish = () => {
    paper.classList.remove("show", "read");
    paper.getAnimations().forEach(x => x.cancel());
    paper.style.visibility = "";
    letterOpen = false;
    const w = document.getElementById("envwrap");
    w.classList.remove("gone");
    w.classList.add("ready");
    w.tabIndex = 0;
  };
}
let lastTap = 0;
reveal.addEventListener("click", () => {
  if (!letterOpen || !document.getElementById("paper").classList.contains("read")) return;
  const now = Date.now();
  if (now - lastTap < 380) { lastTap = 0; closeLetter(); } else lastTap = now;
});
function dropEnvelope() {
  const wrap = document.getElementById("envwrap");
  const drop = document.getElementById("envdrop");
  const tilt = document.getElementById("envtilt");
  const face = document.getElementById("env");
  const sheen = document.getElementById("sheen");
  const shadow = document.getElementById("envshadow");
  // thickness: stacked dark copies behind the face, so the edge shows when it tilts in 3D
  if (!tilt.querySelector(".envlayer")) {
    for (let k = 1; k <= 8; k++) {
      const l = document.createElement("div");
      l.className = "envlayer";
      l.style.backgroundImage = "url(" + face.src + ")";
      l.style.transform = "translateZ(" + (-k * 1.2) + "px)";
      tilt.insertBefore(l, face);
    }
    sheen.style.webkitMaskImage = sheen.style.maskImage = "url(" + face.src + ")";
  }
  const H = -(window.innerHeight / 2 + wrap.offsetHeight + 120);
  const E = "cubic-bezier(.2,.65,.4,1)", G = "cubic-bezier(.5,0,.9,.5)";
  const rows = [
    [0,    0,  H,       -55, 45, -18],
    [.13,  14, H * .94, -35, 32, -13],
    [.26, -10, H * .75, -10, 18, -8],
    [.39,  8,  H * .44,  12, 5,  -2],
    [.52,  0,  0,        28, -10, -4, E],
    [.62,  0, -30,       20, -4,  -2, G],
    [.72,  0,  0,        29, -9,  -3.5, E],
    [.79,  0, -9,        26, -7,  -3, G],
    [.86,  0,  0,        28, -10, -4, E],
    [.93,  0, -2,        27, -9.5, -4, "ease-in"],
    [1,    0,  0,        28, -10, -4]
  ];
  const kf = rows.map(k => ({
    offset: k[0],
    transform: "translate(" + k[1] + "px," + k[2] + "px) rotateX(" + k[3] + "deg) rotateY(" + k[4] + "deg) rotateZ(" + k[5] + "deg)",
    easing: k[6] || "linear"
  }));
  const sk = [[0,0,.8],[.39,.12,.9],[.52,.5,1],[.62,.22,1.12],[.72,.5,1],[.79,.38,1.04],[.86,.5,1],[1,.5,1]].map(k => ({
    offset: k[0], opacity: k[1], transform: "scale(" + k[2] + ")"
  }));
  wrap.style.visibility = "visible";
  const anim = drop.animate(kf, { duration: 2600, fill: "forwards" });
  shadow.animate(sk, { duration: 2600, fill: "forwards", easing: "linear" });
  anim.onfinish = () => {
    tilt.classList.add("landed");
    wrap.classList.add("ready");
    wrap.tabIndex = 0;
    wrap.setAttribute("role", "button");
    wrap.setAttribute("aria-label", "Open the envelope");
    if (!wrap.dataset.bound) {
      wrap.dataset.bound = "1";
      wrap.addEventListener("click", openLetter);
      wrap.addEventListener("keydown", e => {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openLetter(); }
      });
    }
  };
}
function playReveal() {
  if (revealing) return;
  revealing = true;
  rv.style.opacity = 1;
  reveal.classList.add("on");
  setTimeout(() => {
    const d1 = typeInto("guess this");
    setTimeout(() => {
      rv.style.opacity = 0;
      setTimeout(() => {
        rv.style.opacity = 1;
        const d2 = typeInto("of course this is my message for you:3");
        setTimeout(() => {
          rv.style.opacity = 0;
          reveal.classList.add("beige");
          startPetals();
          setTimeout(dropEnvelope, 4000);
        }, d2 + 1400);
      }, 800);
    }, d1 + 1200);
  }, 900);
}

// tapping the notification closes the letter and returns to the chat
function backToChat() {
  const wrap = document.getElementById("envwrap"), paper = document.getElementById("paper");
  const drop = document.getElementById("envdrop"), tilt = document.getElementById("envtilt");
  reveal.classList.remove("on", "beige");
  cancelAnimationFrame(petalRAF); petals = [];
  setTimeout(() => {
    paper.classList.remove("show", "read");
    paper.getAnimations().forEach(x => x.cancel());
    drop.getAnimations().forEach(x => x.cancel());
    document.getElementById("envshadow").getAnimations().forEach(x => x.cancel());
    paper.style.visibility = "";
    wrap.classList.remove("ready", "gone");
    wrap.removeAttribute("tabindex");
    wrap.style.visibility = "";
    tilt.classList.remove("landed");
    rv.style.opacity = 0; rv.innerHTML = "";
    letterOpen = false; revealing = false;
    // the tapped notification shows up in the chat as a new message
    const th = chat.querySelector("#thread");
    if (th && !th.querySelector("[data-love]")) {
      const b = document.createElement("div");
      b.className = "bub";
      b.dataset.love = "1";
      b.textContent = LOVE_MSG;
      th.appendChild(b);
      requestAnimationFrame(() => { th.scrollTop = th.scrollHeight; });
      setTimeout(() => { th.scrollTop = th.scrollHeight; }, 600);
    }
  }, 650);
}

const bstack = document.getElementById("bstack");
function popBanner(m, onTap) {
  if (onTap && bstack.querySelector(".notif.tap:not(.out)")) return; // already showing
  const el = document.createElement("div");
  el.className = "notif";
  el.setAttribute("role", "status");
  el.innerHTML = `${LOGO}
    <div class="copy">
      <div class="top"><span class="app">Messenger</span><span class="when">now</span></div>
      <div class="who">${m.who}</div>
      <div class="msg">${m.text}</div>
    </div>`;
  bstack.appendChild(el);
  void el.offsetWidth;
  el.classList.add("in");
  if (onTap) {
    el.classList.add("tap");
    el.tabIndex = 0;
    el.setAttribute("role", "button");
    const go = () => { if (el.classList.contains("out")) return; el.classList.add("out"); setTimeout(() => el.remove(), 700); onTap(); };
    el.addEventListener("click", go);
    el.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); go(); } });
  }
  if (navigator.vibrate) try { navigator.vibrate(18) } catch (e) {}
  if (!onTap) { // tappable banners stay until tapped
    setTimeout(() => el.classList.add("out"), 3800);
    setTimeout(() => el.remove(), 4600);
  }
  return el;
}

